  {'name':'3 new writes', 'files':['003_new_writes.sql']},
  {'name':'4 OLD restart'},
  {'name':'5 down', 'files':['002_down.sql']},
 ],
 'checks': {name:{'python_file':'readers.py','constant':name} for name in ('OLD','NEW')}
}
