print(h['format_result'](r))
initial = [(1, '첫 항목', b'\\x00\\xff'), (2, 'keep', b'')]
written = [(1, 'updated', b'\\xfe\\x00'), (2, 'keep', b''), (3, 'new', b'\\x80')]
if not r['complete'] or len(r['phases']) "'!= 5:
 raise AssertionError('"'Incomplete sequence')
for i, phase in enumerate(r['phases']):
 expected_rows = initial if i < 2 else written
 for name in ('OLD','NEW'):
  observation = phase['checks'][name]
  if name == 'NEW' and i in (0,4):
   if observation['ok'] or 'no such column: title' not in observation['error']:
    raise AssertionError(observation)
   print(f'CHECK {i+1} {name}: expected inactive error confirmed')
   continue
  observed_columns = ['id', 'label' if i in (0,4) else 'title', 'payload']
  h['assert_rows'](r, i, name, columns=observed_columns, rows=expected_rows)
  if any(type(row[2]) is not bytes for row in observation['rows']):
   raise AssertionError('Nonbinary payload')
  contract_columns = ['id', 'label' if name == 'OLD' else 'title', 'payload']
  try:
   h['assert_rows'](r, i, name, columns=contract_columns, rows=expected_rows)
  except AssertionError as e:
   if not (name == 'OLD' and i in (1,2,3)):
    raise
   print(f'CONTRACT {i+1} {name}: expected incompatibility confirmed: {e}')
  else:
   if name == 'OLD' and i in (1,2,3):
    raise AssertionError('Expected label mismatch missing')
   print(f'CONTRACT {i+1} {name}: PASS (all columns, complete rows, bytes)')
print('All ten observations verified; rollout blocked at step 2; latest writes survive step 5.')
